def read_context(path, maxSize=None, encoding=None, recursive=None, fileTypes=None, chunkNumber=None, **_extra):
    import json, os, datetime, time, hashlib, fnmatch

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _mk_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _mklog_id():
        return "reqlog_" + hashlib.sha256(f"{now}|read_context|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _ensure_logs_shape():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _log(status, repository_id=None, context_request_id=None, detail=None):
        logs = _ensure_logs_shape()
        logs.append(
            {
                "id": _mklog_id(),
                "endpoint": "read_context",
                "status": status,
                "repository_id": repository_id,
                "context_request_id": context_request_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _normalize_rel(p):
        if not isinstance(p, str):
            return None
        p = p.strip().replace("\\", "/")
        if p == "":
            return None
        if p in (".", "./"):
            return "."
        if p.startswith("/"):
            p = p[1:]
        norm = os.path.normpath(p).replace("\\", "/")
        if norm in ("", "."):
            return "."
        if norm == ".." or norm.startswith("../") or "/../" in ("/" + norm + "/"):
            return None
        return norm

    def _resolve_abs(repo_root, rel_path):
        root = os.path.abspath(repo_root)
        target = os.path.abspath(os.path.join(root, "." if rel_path in (None, "", ".") else rel_path))
        try:
            if os.path.commonpath([root, target]) != root:
                return None
        except ValueError:
            return None
        return target

    def _default_ignore_reason(relpath):
        rp = (relpath or "").replace("\\", "/")
        parts = [p for p in rp.split("/") if p not in ("", ".")]
        for seg in parts:
            if seg in (".git", "__pycache__", "node_modules", "dist", ".venv", ".idea", ".vscode"):
                if seg in (".idea", ".vscode"):
                    return f"default_ignore:ide_folder:{seg}/"
                return f"default_ignore:{seg}/"
        base = parts[-1] if parts else rp
        if base.endswith(".pyc"):
            return "default_ignore:*.pyc"
        return None

    def _coerce_bool(v, default):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    def _coerce_int(v, default):
        if v is None:
            return default
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _norm_file_types(ft):
        if ft is None:
            return []
        arr = []
        if isinstance(ft, str):
            arr = [ft]
        elif isinstance(ft, list):
            arr = ft
        else:
            return None
        out = []
        for x in arr:
            if not isinstance(x, str):
                return None
            s = x.strip().lower()
            if s.startswith("."):
                s = s[1:]
            if s == "":
                continue
            if "." in s or "/" in s or "\\" in s:
                return None
            out.append(s)
        # de-dupe stable
        seen = set()
        dedup = []
        for s in out:
            if s not in seen:
                seen.add(s)
                dedup.append(s)
        return dedup

    def _pick_repository_for_path(rel_path, repos):
        # Choose an active/disabled repository that contains this path on disk, else any active/disabled repo.
        candidates = [r for r in repos if isinstance(r, dict) and r.get("status") in ("active", "disabled") and isinstance(r.get("repo_root"), str) and r.get("repo_root").strip() != ""]
        # First: ones where resolved path exists
        for r in candidates:
            ab = _resolve_abs(r["repo_root"], rel_path)
            if not ab:
                continue
            if os.path.exists(ab):
                return r
        # Second: any active/disabled repo that can resolve under root
        for r in candidates:
            if _resolve_abs(r["repo_root"], rel_path):
                return r
        # Third: missing repos as last resort, if path exists (unlikely)
        missing_candidates = [r for r in repos if isinstance(r, dict) and r.get("status") == "missing" and isinstance(r.get("repo_root"), str) and r.get("repo_root").strip() != ""]
        for r in missing_candidates:
            ab = _resolve_abs(r["repo_root"], rel_path)
            if ab and os.path.exists(ab):
                return r
        return None

    def _apply_profile_rules(rel_path, profile):
        # Only additional excludes/includes; default ignore always applies.
        if not isinstance(profile, dict):
            return (True, None)  # selectable
        rp = rel_path.replace("\\", "/")
        include_globs = profile.get("include_globs")
        exclude_globs = profile.get("exclude_globs")
        include_exts = profile.get("include_extensions")
        if include_globs is None:
            include_globs = []
        if exclude_globs is None:
            exclude_globs = []
        if include_exts is None:
            include_exts = []
        if not isinstance(include_globs, list) or not isinstance(exclude_globs, list) or not isinstance(include_exts, list):
            return (True, None)

        # extension filter by profile include_extensions (if non-empty)
        ext = None
        base = os.path.basename(rp)
        if "." in base and not base.startswith("."):
            ext = base.rsplit(".", 1)[1].lower()
        if isinstance(ext, str) and ext.startswith("."):
            ext = ext[1:]
        if include_exts:
            # normalize include_exts
            ie = []
            for e in include_exts:
                if isinstance(e, str) and e.strip():
                    s = e.strip().lower()
                    if s.startswith("."):
                        s = s[1:]
                    ie.append(s)
            if ext not in ie:
                return (False, "profile_exclude:extension")

        # exclude globs override include
        for g in exclude_globs:
            if isinstance(g, str) and g.strip():
                if fnmatch.fnmatch(rp, g.strip()):
                    return (False, f"profile_exclude:{g.strip()}")

        # include globs: if non-empty, must match one
        ig = [g.strip() for g in include_globs if isinstance(g, str) and g.strip()]
        if ig:
            for g in ig:
                if fnmatch.fnmatch(rp, g):
                    return (True, None)
            return (False, "profile_exclude:include_globs_no_match")

        return (True, None)

    def _compute_sha256_file(abs_path):
        h = hashlib.sha256()
        with open(abs_path, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()

    def _inventory_and_select(repo, rel_path, recursive_flag, file_types_norm, profiles_rows):
        repo_id = repo.get("id")
        repo_root = repo.get("repo_root")
        active_profile_id = repo.get("active_profile_id")
        profile = None
        if isinstance(active_profile_id, str) and active_profile_id:
            profile = next((p for p in profiles_rows if isinstance(p, dict) and p.get("id") == active_profile_id and p.get("repository_id") == repo_id and p.get("status") == "active"), None)

        abs_target = _resolve_abs(repo_root, rel_path)
        if abs_target is None:
            return _err("VALIDATION_ERROR", "path must resolve under repo_root (path traversal rejected)", path=rel_path), None, None, None

        if not os.path.exists(abs_target):
            return _err("NOT_FOUND", "path not found under repository root", path=rel_path), None, None, None

        # Load repo_files and build index
        repo_files_rows = _load("repo_files.json")
        if not isinstance(repo_files_rows, list):
            repo_files_rows = []
        by_key = {}
        for rf in repo_files_rows:
            if isinstance(rf, dict) and rf.get("repository_id") == repo_id and isinstance(rf.get("relative_path"), str):
                by_key[rf["relative_path"]] = rf

        selected = []
        # Walk filesystem and upsert repo_files for encountered paths; mark missing for known-but-not-found after walk.
        seen_paths = set()

        def _consider_path(abs_p, is_dir):
            relp = os.path.relpath(abs_p, os.path.abspath(repo_root)).replace("\\", "/")
            if relp in ("", "."):
                relp = "."
            seen_paths.add(relp)

            # determine ignore
            if relp != ".":
                ign = _default_ignore_reason(relp)
                if ign:
                    selectable = False
                    ign_reason = ign
                else:
                    selectable, pr_reason = _apply_profile_rules(relp, profile)
                    ign_reason = pr_reason if not selectable else None
                # fileTypes filter applies only to files and only to selection (but we also mark ignored_reason if filtered?)
                # We'll keep ignored_reason for ignore rules; fileTypes is selection-only and does not mutate status.
            else:
                ign_reason = None

            # compute extension
            ext = None
            if not is_dir and relp != ".":
                base = os.path.basename(relp)
                if "." in base and not base.startswith("."):
                    ext = base.rsplit(".", 1)[1].lower()
                    if ext.startswith("."):
                        ext = ext[1:]

            st = None
            size_bytes = None
            mtime_iso = None
            content_sha = None

            if is_dir:
                st = "ignored" if ign_reason else "indexed"
            else:
                try:
                    stinfo = os.stat(abs_p)
                    size_bytes = int(stinfo.st_size)
                    mtime_iso = datetime.datetime.utcfromtimestamp(stinfo.st_mtime).replace(microsecond=0).isoformat() + "Z"
                except OSError:
                    st = "error"
                if st is None:
                    st = "ignored" if ign_reason else "indexed"

            # upsert row
            existing = by_key.get(relp)
            if existing is None:
                row = {
                    "id": _mk_id("fcs_fil"),
                    "repository_id": repo_id,
                    "relative_path": relp,
                    "is_directory": bool(is_dir),
                    "extension": (None if is_dir else ext),
                    "size_bytes": (None if is_dir else size_bytes),
                    "mtime": (None if is_dir else mtime_iso),
                    "content_sha256": None,  # computed lazily
                    "ignored_reason": ign_reason,
                    "status": st,
                    "created_at": now,
                    "updated_at": now,
                }
                repo_files_rows.append(row)
                by_key[relp] = row
            else:
                # transitions are allowed broadly; enforce enum
                existing["is_directory"] = bool(is_dir)
                existing["extension"] = (None if is_dir else ext)
                existing["size_bytes"] = (None if is_dir else size_bytes)
                existing["mtime"] = (None if is_dir else mtime_iso)
                existing["ignored_reason"] = ign_reason
                # if it was missing but now exists, restore to indexed/ignored/error
                existing["status"] = st
                existing["updated_at"] = now

            # selection logic
            if not is_dir:
                if ign_reason:
                    return
                if file_types_norm:
                    if ext not in file_types_norm:
                        return
                selected.append(relp)

        # Walk
        if os.path.isdir(abs_target):
            if recursive_flag:
                for root, dirs, files in os.walk(abs_target):
                    # Apply default ignore to directory traversal: skip ignored dirs
                    rel_root = os.path.relpath(root, os.path.abspath(repo_root)).replace("\\", "/")
                    if rel_root in ("", "."):
                        rel_root = "."
                    # Prune dirs in-place
                    pruned = []
                    for d in list(dirs):
                        rel_d = os.path.join(rel_root if rel_root != "." else "", d).replace("\\", "/")
                        if rel_d.startswith("/"):
                            rel_d = rel_d[1:]
                        ign = _default_ignore_reason(rel_d)
                        if ign:
                            pruned.append(d)
                    for d in pruned:
                        if d in dirs:
                            dirs.remove(d)
                    # record dirs & files
                    for d in dirs:
                        _consider_path(os.path.join(root, d), True)
                    for f in files:
                        _consider_path(os.path.join(root, f), False)
            else:
                # non-recursive: list direct children
                try:
                    with os.scandir(abs_target) as it:
                        for entry in it:
                            _consider_path(entry.path, entry.is_dir(follow_symlinks=False))
                except OSError:
                    return _err("CONFLICT", "failed to scan directory", path=rel_path), None, None, None
        else:
            _consider_path(abs_target, False)

        # Mark missing for known rows not seen, but only within the subtree when scanning a directory; if file, just that file.
        # Keep lineage: do not delete.
        subtree_prefix = None
        if rel_path == ".":
            subtree_prefix = ""
        else:
            subtree_prefix = rel_path if rel_path != "." else ""
        for rf in repo_files_rows:
            if not (isinstance(rf, dict) and rf.get("repository_id") == repo_id and isinstance(rf.get("relative_path"), str)):
                continue
            rp = rf["relative_path"]
            if subtree_prefix == "":
                in_scope = True
            else:
                if rp == subtree_prefix or rp.startswith(subtree_prefix.rstrip("/") + "/"):
                    in_scope = True
                else:
                    in_scope = False
            if not in_scope:
                continue
            if rp not in seen_paths and rf.get("status") != "missing":
                rf["status"] = "missing"
                rf["updated_at"] = now

        _save("repo_files.json", repo_files_rows)

        # update repositories.last_scan_at
        repos_rows = _load("repositories.json")
        if isinstance(repos_rows, list):
            for r in repos_rows:
                if isinstance(r, dict) and r.get("id") == repo_id:
                    r["last_scan_at"] = now
                    r["updated_at"] = now
                    break
            _save("repositories.json", repos_rows)

        if not selected:
            return _err("NOT_FOUND", "No selectable files after ignore rules / filters", path=rel_path), None, None, None

        # selection fingerprint includes mtimes (and sha if present)
        # Pull mtimes from repo_files rows; compute sha only when chunk materialization reads file content.
        pairs = []
        for rp in sorted(selected):
            rf = by_key.get(rp)
            pairs.append(f"{rp}|{rf.get('mtime') if isinstance(rf, dict) else ''}|{rf.get('content_sha256') if isinstance(rf, dict) else ''}")
        sel_fp = hashlib.sha256(("\n".join(pairs)).encode("utf-8")).hexdigest()

        return None, selected, sel_fp, profile

    # -------- validate inputs --------
    rel = _normalize_rel(path)
    if rel is None:
        _log("error", detail="validation:path")
        return _err("VALIDATION_ERROR", "path is required and must not attempt path traversal", path=path)

    max_sz = _coerce_int(maxSize, 1048576)
    if max_sz is None or max_sz < 1024 or max_sz > 104857600:
        _log("error", detail="validation:maxSize")
        return _err("VALIDATION_ERROR", "maxSize must be an integer in [1024, 104857600]", maxSize=maxSize)

    enc = encoding if encoding is not None else "utf8"
    if not isinstance(enc, str) or enc.strip() == "":
        _log("error", detail="validation:encoding")
        return _err("VALIDATION_ERROR", "encoding must be a non-empty string", encoding=encoding)
    enc = enc.strip()
    allowed_enc = {"utf8", "utf-8", "ascii", "latin1", "utf16le", "ucs2"}
    if enc not in allowed_enc:
        _log("error", detail="validation:encoding_enum")
        return _err("VALIDATION_ERROR", "encoding must be one of the allowed encodings", encoding=enc, allowed=sorted(allowed_enc))

    rec = _coerce_bool(recursive, True)
    if rec is None:
        _log("error", detail="validation:recursive")
        return _err("VALIDATION_ERROR", "recursive must be a boolean", recursive=recursive)

    ft_norm = _norm_file_types(fileTypes)
    if ft_norm is None:
        _log("error", detail="validation:fileTypes")
        return _err("VALIDATION_ERROR", "fileTypes must be a string or array of strings (extensions without dots)", fileTypes=fileTypes)

    chn = _coerce_int(chunkNumber, 0)
    if chn is None:
        _log("error", detail="validation:chunkNumber")
        return _err("VALIDATION_ERROR", "chunkNumber must be an integer", chunkNumber=chunkNumber)
    if chn < 0:
        _log("error", detail="validation:chunkNumber_negative")
        return _err("VALIDATION_ERROR", "chunkNumber must be >= 0", chunkNumber=chn)

    # -------- resolve repository context (ambient) --------
    repos = _load("repositories.json")
    if not isinstance(repos, list):
        repos = []
    profiles_rows = _load("profiles.json")
    if not isinstance(profiles_rows, list):
        profiles_rows = []

    repo = _pick_repository_for_path(rel, repos)
    if not isinstance(repo, dict):
        _log("error", detail="unauthorized:no_repository_context")
        return _err("UNAUTHORIZED", "No repository context available to resolve this path", path=path)

    repo_id = repo.get("id")

    # -------- inventory + selection (updates repo_files) --------
    inv_err, selected_paths, sel_fp, active_profile = _inventory_and_select(repo, rel, rec, ft_norm, profiles_rows)
    if inv_err:
        _log("error", repository_id=repo_id, detail="selection_failed")
        return inv_err

    # -------- reuse or create context_request + chunks --------
    ctx_rows = _load("context_requests.json")
    if not isinstance(ctx_rows, list):
        ctx_rows = []
    chunks_rows = _load("context_chunks.json")
    if not isinstance(chunks_rows, list):
        chunks_rows = []

    # Find equivalent ready request
    def _eq_array(a, b):
        return list(a) == list(b)

    # Normalize stored recursive/refresh may be strings in existing data; handle robustly.
    def _norm_boolish(v):
        if isinstance(v, bool):
            return v
        if isinstance(v, str):
            if v.lower() == "true":
                return True
            if v.lower() == "false":
                return False
        return v

    profile_id = None
    if isinstance(active_profile, dict):
        profile_id = active_profile.get("id")

    equivalent = None
    for cr in ctx_rows:
        if not isinstance(cr, dict):
            continue
        if cr.get("repository_id") != repo_id:
            continue
        if cr.get("request_type") != "read_context":
            continue
        if cr.get("path") != rel:
            continue
        if cr.get("max_size_bytes") != max_sz:
            continue
        if cr.get("encoding") != enc:
            continue
        if _norm_boolish(cr.get("recursive")) != rec:
            continue
        if cr.get("profile_id") != profile_id:
            continue
        fts = cr.get("file_types")
        if not isinstance(fts, list):
            continue
        if not _eq_array(fts, ft_norm):
            continue
        if cr.get("selection_fingerprint") != sel_fp:
            continue
        if cr.get("status") == "ready" and isinstance(cr.get("chunk_count"), int) and cr.get("chunk_count") >= 0:
            equivalent = cr
            break

    # If selection_fingerprint changed vs any ready requests with same params (except fingerprint), mark their chunks stale
    for cr in ctx_rows:
        if not isinstance(cr, dict):
            continue
        if cr.get("repository_id") != repo_id or cr.get("request_type") != "read_context":
            continue
        if cr.get("path") != rel or cr.get("max_size_bytes") != max_sz or cr.get("encoding") != enc:
            continue
        if _norm_boolish(cr.get("recursive")) != rec or cr.get("profile_id") != profile_id:
            continue
        fts = cr.get("file_types")
        if not isinstance(fts, list) or not _eq_array(fts, ft_norm):
            continue
        if cr.get("status") == "ready" and cr.get("selection_fingerprint") and cr.get("selection_fingerprint") != sel_fp:
            old_id = cr.get("id")
            for chk in chunks_rows:
                if isinstance(chk, dict) and chk.get("context_request_id") == old_id and chk.get("status") == "ready":
                    chk["status"] = "stale"
                    chk["updated_at"] = now

    # Materialize if not equivalent
    if equivalent is None:
        ctx_id = _mk_id("fcs_ctx")
        cr = {
            "id": ctx_id,
            "repository_id": repo_id,
            "profile_id": profile_id,
            "request_type": "read_context",
            "path": rel,
            "max_size_bytes": max_sz,
            "encoding": enc,
            "recursive": rec,
            "file_types": ft_norm,
            "refresh": None,
            "chunk_count": None,
            "selection_fingerprint": sel_fp,
            "status": "materializing",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        ctx_rows.append(cr)

        # Build chunks from selected files in order, chunking by approximate byte count of encoded text
        payloads = []
        current = {"files": [], "path": rel, "repository_id": repo_id}
        current_bytes = 0

        # Load repo_files for sha updates
        repo_files_rows = _load("repo_files.json")
        if not isinstance(repo_files_rows, list):
            repo_files_rows = []
        rf_map = {rf.get("id"): rf for rf in repo_files_rows if isinstance(rf, dict) and rf.get("repository_id") == repo_id and isinstance(rf.get("id"), str)}
        rf_by_rel = {rf.get("relative_path"): rf for rf in repo_files_rows if isinstance(rf, dict) and rf.get("repository_id") == repo_id and isinstance(rf.get("relative_path"), str)}

        def _flush():
            nonlocal current, current_bytes, payloads
            payloads.append((current, current_bytes))
            current = {"files": [], "path": rel, "repository_id": repo_id}
            current_bytes = 0

        for rp in sorted(selected_paths):
            abs_p = _resolve_abs(repo.get("repo_root"), rp)
            if not abs_p or not os.path.exists(abs_p) or os.path.isdir(abs_p):
                continue
            try:
                with open(abs_p, "rb") as f:
                    raw = f.read()
            except OSError:
                continue
            try:
                text = raw.decode(enc, errors="replace")
            except Exception:
                text = raw.decode("utf-8", errors="replace")

            approx_bytes = len(text.encode("utf-8", errors="replace"))
            if current["files"] and current_bytes + approx_bytes > max_sz:
                _flush()

            # compute sha and update repo_files
            sha = None
            try:
                sha = hashlib.sha256(raw).hexdigest()
            except Exception:
                sha = None
            rf = rf_by_rel.get(rp)
            if isinstance(rf, dict) and sha:
                if rf.get("content_sha256") != sha:
                    rf["content_sha256"] = sha
                    rf["updated_at"] = now

            current["files"].append(
                {
                    "relative_path": rp,
                    "encoding": enc,
                    "byte_count": approx_bytes,
                    "content": text,
                    "sha256": sha,
                }
            )
            current_bytes += approx_bytes

            if current_bytes >= max_sz:
                _flush()

        if current["files"] or not payloads:
            _flush()

        # Create chunk rows
        # Remove any existing rows for this context_request_id if present (shouldn't) to satisfy unique constraint.
        chunks_rows = [c for c in chunks_rows if not (isinstance(c, dict) and c.get("context_request_id") == ctx_id)]
        for i, (pl, bc) in enumerate(payloads):
            chunks_rows.append(
                {
                    "id": _mk_id("fcs_chk"),
                    "context_request_id": ctx_id,
                    "chunk_number": i,
                    "byte_count": int(bc) if isinstance(bc, int) else 0,
                    "payload": pl,
                    "status": "ready",
                    "created_at": now,
                    "updated_at": now,
                }
            )

        cr["chunk_count"] = len(payloads)
        cr["status"] = "ready"
        cr["updated_at"] = now

        _save("repo_files.json", repo_files_rows)
        _save("context_requests.json", ctx_rows)
        _save("context_chunks.json", chunks_rows)
        equivalent = cr
    else:
        # persist stale changes if any
        _save("context_chunks.json", chunks_rows)

    # Validate chunkNumber against chunk_count
    cc = equivalent.get("chunk_count")
    if not isinstance(cc, int) or cc < 0:
        _log("error", repository_id=repo_id, context_request_id=equivalent.get("id"), detail="invalid_chunk_count")
        return _err("CONFLICT", "cached request has invalid chunk_count", context_request_id=equivalent.get("id"))
    if chn >= cc:
        _log("error", repository_id=repo_id, context_request_id=equivalent.get("id"), detail="chunk_out_of_range")
        return _err("VALIDATION_ERROR", f"chunkNumber out of range (chunk_count={cc})", chunkNumber=chn, chunk_count=cc)

    # Fetch chunk
    ctx_id = equivalent.get("id")
    chunk = next((c for c in chunks_rows if isinstance(c, dict) and c.get("context_request_id") == ctx_id and c.get("chunk_number") == chn), None)
    if not isinstance(chunk, dict):
        _log("error", repository_id=repo_id, context_request_id=ctx_id, detail="chunk_not_found")
        return _err("NOT_FOUND", "chunk not found for context request", context_request_id=ctx_id, chunkNumber=chn)

    if chunk.get("status") == "stale":
        _log("error", repository_id=repo_id, context_request_id=ctx_id, detail="chunk_stale")
        return _err("INVALID_TRANSITION", "requested chunk is stale; re-materialize by calling get_chunk_count/read_context again", context_request_id=ctx_id, chunkNumber=chn)

    _log("ok", repository_id=repo_id, context_request_id=ctx_id, detail="served")
    return {
        "context_request": {
            "id": ctx_id,
            "repository_id": repo_id,
            "path": equivalent.get("path"),
            "request_type": equivalent.get("request_type"),
            "profile_id": equivalent.get("profile_id"),
            "max_size_bytes": equivalent.get("max_size_bytes"),
            "encoding": equivalent.get("encoding"),
            "recursive": equivalent.get("recursive"),
            "file_types": equivalent.get("file_types"),
            "chunk_count": equivalent.get("chunk_count"),
            "selection_fingerprint": equivalent.get("selection_fingerprint"),
            "status": equivalent.get("status"),
            "updated_at": equivalent.get("updated_at"),
        },
        "chunk": {
            "id": chunk.get("id"),
            "chunkNumber": chunk.get("chunk_number"),
            "byte_count": chunk.get("byte_count"),
            "payload": chunk.get("payload"),
            "status": chunk.get("status"),
        },
    }

def get_chunk_count(path, encoding=None, maxSize=None, recursive=None, fileTypes=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, repository_id=None, context_request_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "reqlog_" + hashlib.sha256(f"{now}|get_chunk_count|{time.time()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": "get_chunk_count",
                "status": status,
                "repository_id": repository_id,
                "context_request_id": context_request_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _norm_rel(p):
        if not isinstance(p, str):
            return None
        p = p.strip().replace("\\", "/")
        if p == "":
            return None
        if p.startswith("/"):
            p = p[1:]
        p2 = os.path.normpath(p).replace("\\", "/")
        if p2 in ("", "."):
            return "."
        if p2.startswith("../") or p2 == "..":
            return None
        return p2

    def _normalize_filetypes(ft):
        if ft is None:
            return []
        if isinstance(ft, str):
            ft = [ft]
        if not isinstance(ft, list):
            return None
        out = []
        for x in ft:
            if not isinstance(x, str):
                return None
            s = x.strip().lower()
            if s.startswith("."):
                s = s[1:]
            if s == "":
                continue
            if "." in s:
                return None
            out.append(s)
        seen = set()
        uniq = []
        for s in out:
            if s not in seen:
                seen.add(s)
                uniq.append(s)
        return uniq

    allowed_enc = {"utf8", "utf-8", "ascii", "latin1", "utf16le", "ucs2"}

    rel = _norm_rel(path)
    if rel is None:
        _log("error", detail="validation:path")
        return _err("VALIDATION_ERROR", "path must be a non-empty, repo-relative path and must not escape the repository root")

    if maxSize is None:
        maxSize = 1048576
    if encoding is None:
        encoding = "utf8"
    if recursive is None:
        recursive = True
    if fileTypes is None:
        fileTypes = []

    if not isinstance(maxSize, (int, float)) or isinstance(maxSize, bool):
        _log("error", detail="validation:maxSize")
        return _err("VALIDATION_ERROR", "maxSize must be a number")
    try:
        max_size_i = int(maxSize)
    except Exception:
        _log("error", detail="validation:maxSize")
        return _err("VALIDATION_ERROR", "maxSize must be an integer number of bytes")
    if max_size_i < 1024 or max_size_i > 104857600:
        _log("error", detail="validation:maxSize_range")
        return _err("VALIDATION_ERROR", "maxSize must be within [1024, 104857600]")

    if not isinstance(encoding, str) or encoding.strip().lower() not in allowed_enc:
        _log("error", detail="validation:encoding")
        return _err("VALIDATION_ERROR", "encoding must be one of: utf8, utf-8, ascii, latin1, utf16le, ucs2")
    enc = encoding.strip().lower()

    if not isinstance(recursive, bool):
        _log("error", detail="validation:recursive")
        return _err("VALIDATION_ERROR", "recursive must be a boolean")

    fts = _normalize_filetypes(fileTypes)
    if fts is None:
        _log("error", detail="validation:fileTypes")
        return _err("VALIDATION_ERROR", "fileTypes must be a string or array of strings (extensions without dots), lowercase-able, and must not contain '.'")

    repos = _load("repositories.json")
    repo_files = _load("repo_files.json")
    context_requests = _load("context_requests.json")

    if not isinstance(repos, list):
        repos = []
    if not isinstance(repo_files, list):
        repo_files = []
    if not isinstance(context_requests, list):
        context_requests = []

    # Resolve repository similar to read_context: prefer repo_files match, else any usable repo_root.
    candidate_repo_ids = []
    for rf in repo_files:
        if isinstance(rf, dict) and rf.get("relative_path") == rel:
            rid = rf.get("repository_id")
            if isinstance(rid, str) and rid:
                candidate_repo_ids.append(rid)

    def _repo_ok(r):
        return isinstance(r, dict) and isinstance(r.get("id"), str) and isinstance(r.get("repo_root"), str) and r.get("repo_root").strip() != ""

    repo_by_id = {r.get("id"): r for r in repos if _repo_ok(r)}
    resolved_repo = None
    for rid in candidate_repo_ids:
        r = repo_by_id.get(rid)
        if r:
            resolved_repo = r
            break

    if resolved_repo is None:
        # fallback: choose a repository with any repo_root
        for r in repos:
            if _repo_ok(r):
                resolved_repo = r
                break

    if resolved_repo is None:
        _log("error", detail="unauthorized:no_usable_repository")
        return _err("UNAUTHORIZED", "No usable repository root is configured")

    repository_id = resolved_repo["id"]

    # Reuse equivalent request (including request_type='get_chunk_count')
    def _req_equiv(cr):
        if not isinstance(cr, dict):
            return False
        if cr.get("repository_id") != repository_id:
            return False
        if cr.get("request_type") != "get_chunk_count":
            return False
        if cr.get("path") != rel:
            return False
        if int(cr.get("max_size_bytes") or -1) != max_size_i:
            return False
        if (cr.get("encoding") or "").lower() != enc:
            return False
        if bool(cr.get("recursive")) != bool(recursive):
            return False
        ft_row = cr.get("file_types")
        if not isinstance(ft_row, list):
            ft_row = []
        ft_row_norm = []
        for x in ft_row:
            if isinstance(x, str):
                s = x.strip().lower()
                if s.startswith("."):
                    s = s[1:]
                if s and "." not in s:
                    ft_row_norm.append(s)
        return ft_row_norm == fts

    for cr in context_requests:
        if _req_equiv(cr) and isinstance(cr.get("chunk_count"), int) and cr.get("chunk_count") >= 0:
            _log("ok", repository_id=repository_id, context_request_id=cr.get("id"), detail="reused")
            return {"chunk_count": cr.get("chunk_count"), "context_request_id": cr.get("id")}

    # Otherwise: compute from inventory without materializing chunks (per business rule)
    # Select matching repo_files under path, apply status/ignore, recursive and extension filtering.
    prefix = "" if rel == "." else (rel.rstrip("/") + "/")
    selected = []
    for rf in repo_files:
        if not isinstance(rf, dict):
            continue
        if rf.get("repository_id") != repository_id:
            continue
        rp = rf.get("relative_path")
        if not isinstance(rp, str) or rp == "":
            continue
        if rel == ".":
            in_scope = True
        else:
            if rp == rel:
                in_scope = True
            elif rp.startswith(prefix):
                in_scope = True
            else:
                in_scope = False
        if not in_scope:
            continue
        if not recursive and rel != "." and rp != rel and rp.startswith(prefix):
            rest = rp[len(prefix) :]
            if "/" in rest:
                continue
        if rf.get("status") == "ignored":
            continue
        if rf.get("ignored_reason") is not None:
            continue
        if rf.get("is_directory") is True:
            continue
        if fts:
            ext = rf.get("extension")
            if not isinstance(ext, str) or ext.lower() not in fts:
                continue
        if rf.get("status") in ("missing", "error"):
            continue
        selected.append(rf)

    if not selected:
        # create a request row with status=error similar to existing store behavior
        ctx_id = "fcs_ctx_" + hashlib.sha256(f"{now}|get_chunk_count|{repository_id}|{rel}|{time.time()}".encode("utf-8")).hexdigest()[:26]
        row = {
            "id": ctx_id,
            "repository_id": repository_id,
            "profile_id": None,
            "request_type": "get_chunk_count",
            "path": rel,
            "max_size_bytes": max_size_i,
            "encoding": enc,
            "recursive": bool(recursive),
            "file_types": fts,
            "refresh": None,
            "chunk_count": None,
            "selection_fingerprint": None,
            "status": "error",
            "error_message": "No selectable files after ignore rules",
            "created_at": now,
            "updated_at": now,
        }
        context_requests.append(row)
        _save("context_requests.json", context_requests)
        _log("error", repository_id=repository_id, context_request_id=ctx_id, detail="selection:empty")
        return _err("NOT_FOUND", "No selectable files after ignore rules", context_request_id=ctx_id)

    # approximate chunk count by summing sizes and dividing by maxSize, at least 1
    total = 0
    for rf in selected:
        sz = rf.get("size_bytes")
        if isinstance(sz, int) and sz >= 0:
            total += sz
        else:
            total += 0
    chunk_count = max(1, (total + max_size_i - 1) // max_size_i)

    ctx_id = "fcs_ctx_" + hashlib.sha256(f"{now}|get_chunk_count|{repository_id}|{rel}|{enc}|{max_size_i}|{recursive}|{fts}".encode("utf-8")).hexdigest()[:26]
    row = {
        "id": ctx_id,
        "repository_id": repository_id,
        "profile_id": None,
        "request_type": "get_chunk_count",
        "path": rel,
        "max_size_bytes": max_size_i,
        "encoding": enc,
        "recursive": bool(recursive),
        "file_types": fts,
        "refresh": None,
        "chunk_count": int(chunk_count),
        "selection_fingerprint": "sel_" + hashlib.sha256(f"{repository_id}|{rel}|{len(selected)}|{total}|{now}".encode("utf-8")).hexdigest()[:24],
        "status": "ready",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    context_requests.append(row)
    _save("context_requests.json", context_requests)
    _log("ok", repository_id=repository_id, context_request_id=ctx_id, detail="computed")
    return {"chunk_count": int(chunk_count), "context_request_id": ctx_id}

def set_profile(profile_name, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mklog_id():
        return "reqlog_" + hashlib.sha256(f"{now}|set_profile|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _log(status, repository_id=None, profile_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mklog_id(),
                "endpoint": "set_profile",
                "status": status,
                "repository_id": repository_id,
                "profile_id": profile_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(profile_name, str) or not profile_name.strip():
        _log("error", detail="validation:profile_name")
        return _err("VALIDATION_ERROR", "profile_name is required and must be non-empty", profile_name=profile_name)

    pname = profile_name.strip()

    repos = _load("repositories.json")
    profiles = _load("profiles.json")
    if not isinstance(repos, list):
        repos = []
    if not isinstance(profiles, list):
        profiles = []

    # Prefer repository that already has this profile name among active profiles.
    candidates = []
    for p in profiles:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        if p.get("name") != pname:
            continue
        rid = p.get("repository_id")
        if not isinstance(rid, str) or not rid:
            continue
        r = next((rr for rr in repos if isinstance(rr, dict) and rr.get("id") == rid), None)
        if not isinstance(r, dict):
            continue
        # prefer non-missing repositories
        prio = 0 if r.get("status") in ("active", "disabled") else 1
        candidates.append((prio, r, p))

    if not candidates:
        _log("error", detail="not_found:profile_name")
        return _err("NOT_FOUND", "No active profile with that name exists", profile_name=pname)

    candidates.sort(key=lambda x: x[0])
    _, repo, prof = candidates[0]

    # Mutate repository active_profile_id
    rid = repo.get("id")
    pid = prof.get("id")
    updated = False
    for r in repos:
        if isinstance(r, dict) and r.get("id") == rid:
            if r.get("active_profile_id") == pid:
                # idempotent
                _log("ok", repository_id=rid, profile_id=pid, detail="idempotent")
                return {
                    "repository": r,
                    "active_profile": prof,
                }
            r["active_profile_id"] = pid
            r["updated_at"] = now
            updated = True
            repo = r
            break

    if not updated:
        _log("error", repository_id=rid, profile_id=pid, detail="repo_not_found_for_profile")
        return _err("NOT_FOUND", "Repository for profile not found", repository_id=rid, profile_id=pid)

    _save("repositories.json", repos)
    _log("ok", repository_id=rid, profile_id=pid, detail="updated")
    return {
        "repository": repo,
        "active_profile": prof,
    }

def get_profile_context(refresh=None, **_extra):
    import json, os, datetime, time, hashlib, fnmatch

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _mk_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _mklog_id():
        return "reqlog_" + hashlib.sha256(f"{now}|get_profile_context|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _log(status, repository_id=None, profile_id=None, context_request_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mklog_id(),
                "endpoint": "get_profile_context",
                "status": status,
                "repository_id": repository_id,
                "profile_id": profile_id,
                "context_request_id": context_request_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _default_ignore_reason(relpath):
        rp = (relpath or "").replace("\\", "/")
        parts = [p for p in rp.split("/") if p not in ("", ".")]
        for seg in parts:
            if seg in (".git", "__pycache__", "node_modules", "dist", ".venv", ".idea", ".vscode"):
                if seg in (".idea", ".vscode"):
                    return f"default_ignore:ide_folder:{seg}/"
                return f"default_ignore:{seg}/"
        base = parts[-1] if parts else rp
        if base.endswith(".pyc"):
            return "default_ignore:*.pyc"
        return None

    def _resolve_abs(repo_root, rel_path):
        root = os.path.abspath(repo_root)
        target = os.path.abspath(os.path.join(root, "." if rel_path in (None, "", ".") else rel_path))
        try:
            if os.path.commonpath([root, target]) != root:
                return None
        except ValueError:
            return None
        return target

    def _norm_bool(v, default):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    def _apply_profile_rules(rel_path, profile):
        if not isinstance(profile, dict):
            return (True, None)
        rp = rel_path.replace("\\", "/")
        include_globs = profile.get("include_globs") or []
        exclude_globs = profile.get("exclude_globs") or []
        include_exts = profile.get("include_extensions") or []
        if not isinstance(include_globs, list) or not isinstance(exclude_globs, list) or not isinstance(include_exts, list):
            return (True, None)

        base = os.path.basename(rp)
        ext = None
        if "." in base and not base.startswith("."):
            ext = base.rsplit(".", 1)[1].lower()
            if ext.startswith("."):
                ext = ext[1:]

        norm_exts = []
        for e in include_exts:
            if isinstance(e, str) and e.strip():
                s = e.strip().lower()
                if s.startswith("."):
                    s = s[1:]
                norm_exts.append(s)

        if norm_exts:
            if ext not in norm_exts:
                return (False, "profile_exclude:extension")

        for g in exclude_globs:
            if isinstance(g, str) and g.strip() and fnmatch.fnmatch(rp, g.strip()):
                return (False, f"profile_exclude:{g.strip()}")

        ig = [g.strip() for g in include_globs if isinstance(g, str) and g.strip()]
        if ig:
            for g in ig:
                if fnmatch.fnmatch(rp, g):
                    return (True, None)
            return (False, "profile_exclude:include_globs_no_match")

        return (True, None)

    # validate refresh
    ref = _norm_bool(refresh, False)
    if ref is None:
        _log("error", detail="validation:refresh")
        return _err("VALIDATION_ERROR", "refresh must be a boolean", refresh=refresh)

    repos = _load("repositories.json")
    profiles = _load("profiles.json")
    if not isinstance(repos, list):
        repos = []
    if not isinstance(profiles, list):
        profiles = []

    # Find a repository that has an active_profile_id pointing to an active profile
    repo = None
    profile = None
    for r in repos:
        if not isinstance(r, dict):
            continue
        if r.get("status") not in ("active", "disabled"):
            continue
        pid = r.get("active_profile_id")
        if not isinstance(pid, str) or not pid:
            continue
        p = next((pp for pp in profiles if isinstance(pp, dict) and pp.get("id") == pid and pp.get("repository_id") == r.get("id") and pp.get("status") == "active"), None)
        if isinstance(p, dict):
            repo = r
            profile = p
            break

    if not isinstance(repo, dict) or not isinstance(profile, dict):
        _log("error", detail="not_found:no_active_profile_set")
        return _err("NOT_FOUND", "No active profile is set")

    repo_id = repo.get("id")
    profile_id = profile.get("id")

    # Parameters from profile defaults
    max_sz = profile.get("max_size_default_bytes")
    enc = profile.get("encoding_default")
    rec = profile.get("recursive_default")

    if not isinstance(max_sz, int) or max_sz < 1024 or max_sz > 104857600:
        _log("error", repository_id=repo_id, profile_id=profile_id, detail="validation:max_size_default_bytes")
        return _err("CONFLICT", "Profile has invalid max_size_default_bytes", profile_id=profile_id)
    allowed_enc = {"utf8", "utf-8", "ascii", "latin1", "utf16le", "ucs2"}
    if not isinstance(enc, str) or enc not in allowed_enc:
        _log("error", repository_id=repo_id, profile_id=profile_id, detail="validation:encoding_default")
        return _err("CONFLICT", "Profile has invalid encoding_default", profile_id=profile_id)
    if not isinstance(rec, bool):
        _log("error", repository_id=repo_id, profile_id=profile_id, detail="validation:recursive_default")
        return _err("CONFLICT", "Profile has invalid recursive_default", profile_id=profile_id)

    # Select files under repo root based on ignore + profile rules (and update repo_files if refresh)
    repo_root = repo.get("repo_root")
    if not isinstance(repo_root, str) or not repo_root.strip():
        _log("error", repository_id=repo_id, profile_id=profile_id, detail="repo_root_missing")
        return _err("CONFLICT", "Repository has invalid repo_root", repository_id=repo_id)

    abs_root = _resolve_abs(repo_root, ".")
    if abs_root is None or not os.path.isdir(abs_root):
        # repository root missing
        _log("error", repository_id=repo_id, profile_id=profile_id, detail="repo_root_not_found")
        return _err("NOT_FOUND", "Repository root not found on disk", repository_id=repo_id, repo_root=repo_root)

    repo_files_rows = _load("repo_files.json")
    if not isinstance(repo_files_rows, list):
        repo_files_rows = []
    by_rel = {}
    for rf in repo_files_rows:
        if isinstance(rf, dict) and rf.get("repository_id") == repo_id and isinstance(rf.get("relative_path"), str):
            by_rel[rf["relative_path"]] = rf

    selected = []
    seen = set()

    def _upsert(abs_p, is_dir):
        relp = os.path.relpath(abs_p, os.path.abspath(repo_root)).replace("\\", "/")
        if relp in ("", "."):
            relp = "."
        seen.add(relp)

        ign = None
        if relp != ".":
            ign = _default_ignore_reason(relp)
            if not ign:
                selectable, pr = _apply_profile_rules(relp, profile)
                if not selectable:
                    ign = pr

        ext = None
        if not is_dir and relp != ".":
            base = os.path.basename(relp)
            if "." in base and not base.startswith("."):
                ext = base.rsplit(".", 1)[1].lower()

        size_bytes = None
        mtime_iso = None
        status = None
        if is_dir:
            status = "ignored" if ign else "indexed"
        else:
            try:
                st = os.stat(abs_p)
                size_bytes = int(st.st_size)
                mtime_iso = datetime.datetime.utcfromtimestamp(st.st_mtime).replace(microsecond=0).isoformat() + "Z"
                status = "ignored" if ign else "indexed"
            except OSError:
                status = "error"

        if ref:
            existing = by_rel.get(relp)
            if existing is None:
                repo_files_rows.append(
                    {
                        "id": _mk_id("fcs_fil"),
                        "repository_id": repo_id,
                        "relative_path": relp,
                        "is_directory": bool(is_dir),
                        "extension": (None if is_dir else ext),
                        "size_bytes": (None if is_dir else size_bytes),
                        "mtime": (None if is_dir else mtime_iso),
                        "content_sha256": None,
                        "ignored_reason": ign,
                        "status": status,
                        "created_at": now,
                        "updated_at": now,
                    }
                )
                by_rel[relp] = repo_files_rows[-1]
            else:
                existing["is_directory"] = bool(is_dir)
                existing["extension"] = (None if is_dir else ext)
                existing["size_bytes"] = (None if is_dir else size_bytes)
                existing["mtime"] = (None if is_dir else mtime_iso)
                existing["ignored_reason"] = ign
                existing["status"] = status
                existing["updated_at"] = now

        if (not is_dir) and (not ign):
            selected.append(relp)

    # Walk (always based on filesystem)
    for root, dirs, files in os.walk(abs_root):
        # prune ignored dirs
        pruned = []
        rel_root = os.path.relpath(root, os.path.abspath(repo_root)).replace("\\", "/")
        if rel_root in ("", "."):
            rel_root = "."
        for d in list(dirs):
            rel_d = os.path.join(rel_root if rel_root != "." else "", d).replace("\\", "/")
            if rel_d.startswith("/"):
                rel_d = rel_d[1:]
            if _default_ignore_reason(rel_d):
                pruned.append(d)
        for d in pruned:
            if d in dirs:
                dirs.remove(d)
        for d in dirs:
            _upsert(os.path.join(root, d), True)
        for f in files:
            _upsert(os.path.join(root, f), False)

    if ref:
        # mark missing for previously known paths not present now
        for rf in repo_files_rows:
            if not (isinstance(rf, dict) and rf.get("repository_id") == repo_id and isinstance(rf.get("relative_path"), str)):
                continue
            if rf["relative_path"] not in seen and rf.get("status") != "missing":
                rf["status"] = "missing"
                rf["updated_at"] = now
        _save("repo_files.json", repo_files_rows)
        # update repo scan time
        for r in repos:
            if isinstance(r, dict) and r.get("id") == repo_id:
                r["last_scan_at"] = now
                r["updated_at"] = now
                break
        _save("repositories.json", repos)

    if not selected:
        _log("error", repository_id=repo_id, profile_id=profile_id, detail="no_selectable_files")
        return _err("NOT_FOUND", "No selectable files after ignore rules / profile rules")

    # selection fingerprint uses mtimes from repo_files if present (best-effort)
    pairs = []
    for rp in sorted(selected):
        rf = by_rel.get(rp)
        pairs.append(f"{rp}|{(rf.get('mtime') if isinstance(rf, dict) else '')}|{(rf.get('content_sha256') if isinstance(rf, dict) else '')}")
    sel_fp = hashlib.sha256(("\n".join(pairs)).encode("utf-8")).hexdigest()

    ctx_rows = _load("context_requests.json")
    if not isinstance(ctx_rows, list):
        ctx_rows = []
    chunks_rows = _load("context_chunks.json")
    if not isinstance(chunks_rows, list):
        chunks_rows = []

    # Reuse ready request if refresh=false and fingerprint matches
    reusable = None
    if not ref:
        for cr in ctx_rows:
            if not isinstance(cr, dict):
                continue
            if cr.get("repository_id") != repo_id:
                continue
            if cr.get("profile_id") != profile_id:
                continue
            if cr.get("request_type") != "get_profile_context":
                continue
            if cr.get("path") != ".":
                continue
            if cr.get("max_size_bytes") != max_sz or cr.get("encoding") != enc or cr.get("recursive") != rec:
                continue
            if cr.get("file_types") != []:
                continue
            if cr.get("refresh") not in (False, "False", None):
                # historical may have null; accept
                pass
            if cr.get("selection_fingerprint") != sel_fp:
                continue
            if cr.get("status") == "ready" and isinstance(cr.get("chunk_count"), int) and cr.get("chunk_count") >= 0:
                reusable = cr
                break

    # mark stale chunks for prior ready requests with same params but different fingerprint
    for cr in ctx_rows:
        if not isinstance(cr, dict):
            continue
        if cr.get("repository_id") != repo_id or cr.get("profile_id") != profile_id:
            continue
        if cr.get("request_type") != "get_profile_context" or cr.get("path") != ".":
            continue
        if cr.get("max_size_bytes") != max_sz or cr.get("encoding") != enc or cr.get("recursive") != rec:
            continue
        if cr.get("file_types") != []:
            continue
        if cr.get("status") == "ready" and cr.get("selection_fingerprint") and cr.get("selection_fingerprint") != sel_fp:
            old_id = cr.get("id")
            for chk in chunks_rows:
                if isinstance(chk, dict) and chk.get("context_request_id") == old_id and chk.get("status") == "ready":
                    chk["status"] = "stale"
                    chk["updated_at"] = now

    if reusable is None:
        ctx_id = _mk_id("fcs_ctx")
        cr = {
            "id": ctx_id,
            "repository_id": repo_id,
            "profile_id": profile_id,
            "request_type": "get_profile_context",
            "path": ".",
            "max_size_bytes": max_sz,
            "encoding": enc,
            "recursive": rec,
            "file_types": [],
            "refresh": bool(ref),
            "chunk_count": None,
            "selection_fingerprint": sel_fp,
            "status": "materializing",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        ctx_rows.append(cr)

        # materialize as chunks then return concatenated payload across all chunks
        payloads = []
        current = {"files": [], "path": ".", "repository_id": repo_id, "profile_id": profile_id}
        current_bytes = 0

        def _flush():
            nonlocal current, current_bytes, payloads
            payloads.append((current, current_bytes))
            current = {"files": [], "path": ".", "repository_id": repo_id, "profile_id": profile_id}
            current_bytes = 0

        for rp in sorted(selected):
            abs_p = _resolve_abs(repo_root, rp)
            if not abs_p or not os.path.exists(abs_p) or os.path.isdir(abs_p):
                continue
            try:
                with open(abs_p, "rb") as f:
                    raw = f.read()
            except OSError:
                continue
            try:
                text = raw.decode(enc, errors="replace")
            except Exception:
                text = raw.decode("utf-8", errors="replace")

            approx_bytes = len(text.encode("utf-8", errors="replace"))
            if current["files"] and current_bytes + approx_bytes > max_sz:
                _flush()

            sha = hashlib.sha256(raw).hexdigest()
            if ref:
                rf = by_rel.get(rp)
                if isinstance(rf, dict) and rf.get("content_sha256") != sha:
                    rf["content_sha256"] = sha
                    rf["updated_at"] = now

            current["files"].append({"relative_path": rp, "encoding": enc, "byte_count": approx_bytes, "content": text, "sha256": sha})
            current_bytes += approx_bytes
            if current_bytes >= max_sz:
                _flush()

        if current["files"] or not payloads:
            _flush()

        # write chunks
        chunks_rows = [c for c in chunks_rows if not (isinstance(c, dict) and c.get("context_request_id") == ctx_id)]
        for i, (pl, bc) in enumerate(payloads):
            chunks_rows.append(
                {
                    "id": _mk_id("fcs_chk"),
                    "context_request_id": ctx_id,
                    "chunk_number": i,
                    "byte_count": int(bc) if isinstance(bc, int) else 0,
                    "payload": pl,
                    "status": "ready",
                    "created_at": now,
                    "updated_at": now,
                }
            )

        cr["chunk_count"] = len(payloads)
        cr["status"] = "ready"
        cr["updated_at"] = now

        if ref:
            _save("repo_files.json", repo_files_rows)
        _save("context_requests.json", ctx_rows)
        _save("context_chunks.json", chunks_rows)
        reusable = cr
    else:
        _save("context_chunks.json", chunks_rows)

    # Return as single payload (concatenate chunk payloads)
    ctx_id = reusable.get("id")
    ready_chunks = sorted(
        [c for c in chunks_rows if isinstance(c, dict) and c.get("context_request_id") == ctx_id and c.get("status") == "ready"],
        key=lambda c: c.get("chunk_number", 0),
    )
    files_out = []
    total_bytes = 0
    for c in ready_chunks:
        pl = c.get("payload")
        if isinstance(pl, dict) and isinstance(pl.get("files"), list):
            for f in pl["files"]:
                if isinstance(f, dict):
                    files_out.append(f)
                    bc = f.get("byte_count")
                    if isinstance(bc, int):
                        total_bytes += bc

    _log("ok", repository_id=repo_id, profile_id=profile_id, context_request_id=ctx_id, detail="served")
    return {
        "context_request": {
            "id": ctx_id,
            "repository_id": repo_id,
            "profile_id": profile_id,
            "request_type": reusable.get("request_type"),
            "path": reusable.get("path"),
            "max_size_bytes": reusable.get("max_size_bytes"),
            "encoding": reusable.get("encoding"),
            "recursive": reusable.get("recursive"),
            "chunk_count": reusable.get("chunk_count"),
            "selection_fingerprint": reusable.get("selection_fingerprint"),
            "status": reusable.get("status"),
            "updated_at": reusable.get("updated_at"),
        },
        "context": {
            "byte_count": total_bytes,
            "files": files_out,
        },
    }

def generate_outline(path, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mklog_id():
        return "reqlog_" + hashlib.sha256(f"{now}|generate_outline|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _log(status, repository_id=None, repo_file_id=None, outline_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mklog_id(),
                "endpoint": "generate_outline",
                "status": status,
                "repository_id": repository_id,
                "repo_file_id": repo_file_id,
                "outline_id": outline_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _norm_rel(p):
        if not isinstance(p, str):
            return None
        p = p.strip().replace("\\", "/")
        if p == "":
            return None
        if p.startswith("/"):
            p = p[1:]
        p2 = os.path.normpath(p).replace("\\", "/")
        if p2 in ("", "."):
            return "."
        if p2 == ".." or p2.startswith("../"):
            return None
        return p2

    def _id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24]

    rel = _norm_rel(path)
    if rel is None or rel == ".":
        _log("error", detail="validation:path")
        return _err("VALIDATION_ERROR", "path must be a file path under the repository root (no traversal)", path=path)

    repo_files = _load("repo_files.json")
    repositories = _load("repositories.json")
    code_outlines = _load("code_outlines.json")

    if not isinstance(repo_files, list):
        repo_files = []
    if not isinstance(repositories, list):
        repositories = []
    if not isinstance(code_outlines, list):
        code_outlines = []

    # Find file in any repository: prefer indexed and non-ignored
    matches = []
    for rf in repo_files:
        if not isinstance(rf, dict):
            continue
        if rf.get("relative_path") != rel:
            continue
        rid = rf.get("repository_id")
        if not isinstance(rid, str) or not rid:
            continue
        repo = next((r for r in repositories if isinstance(r, dict) and r.get("id") == rid), None)
        if not isinstance(repo, dict):
            continue
        st = rf.get("status")
        ig = rf.get("ignored_reason")
        pr = 0
        if st != "indexed":
            pr += 3
        if ig:
            pr += 2
        if repo.get("status") != "active":
            pr += 1
        matches.append((pr, repo, rf))

    if not matches:
        _log("error", detail="not_found:file")
        return _err("NOT_FOUND", "file not found in any repository", path=rel)

    matches.sort(key=lambda x: x[0])
    _, repo, rf = matches[0]
    rid = repo.get("id")
    rfid = rf.get("id")

    # Supported languages mapping
    ext = rf.get("extension")
    if not isinstance(ext, str) or ext.strip() == "":
        _log("error", repository_id=rid, repo_file_id=rfid, detail="validation:unsupported_extension")
        return _err("VALIDATION_ERROR", "Unsupported file type for outline generation", path=rel, extension=ext)

    ext = ext.lower()
    if ext == "py":
        language = "python"
        parser_version = "outline-py@1.9.0"
    elif ext in ("js", "jsx"):
        language = "javascript"
        parser_version = "outline-js@2.6.1"
    elif ext in ("ts", "tsx"):
        language = "typescript"
        parser_version = "outline@2.6.1"
    else:
        _log("error", repository_id=rid, repo_file_id=rfid, detail="validation:unsupported_extension")
        return _err("VALIDATION_ERROR", "Unsupported file type for outline generation", path=rel, extension=ext)

    content_sha = rf.get("content_sha256")
    if not isinstance(content_sha, str) or not content_sha:
        # Cannot reuse cache without content hash
        content_sha = "unknown"

    # Reuse existing READY outline when match (repo_file_id + parser_version + content_sha256)
    reuse = next(
        (
            o
            for o in code_outlines
            if isinstance(o, dict)
            and o.get("repository_id") == rid
            and o.get("repo_file_id") == rfid
            and o.get("parser_version") == parser_version
            and o.get("content_sha256") == content_sha
            and o.get("status") == "ready"
        ),
        None,
    )
    if reuse:
        _log("ok", repository_id=rid, repo_file_id=rfid, outline_id=reuse.get("id"), detail="reused_ready")
        return {"repository": repo, "repo_file": rf, "outline": reuse}

    # Mark prior ones for same repo_file_id + parser_version as stale (ready->stale)
    for o in code_outlines:
        if not isinstance(o, dict):
            continue
        if o.get("repository_id") == rid and o.get("repo_file_id") == rfid and o.get("parser_version") == parser_version and o.get("status") == "ready":
            o["status"] = "stale"
            o["updated_at"] = now

    # Create a new outline row (server would actually parse file; offline implementation stores a minimal outline)
    outline_obj = {
        "path": rel,
        "language": language,
        "summary": "Outline generation is not executed offline; this is a cached/placeholder structure.",
        "symbols": [],
    }
    new_row = {
        "id": _id("fcs_out"),
        "repository_id": rid,
        "repo_file_id": rfid,
        "relative_path": rel,
        "language": language,
        "parser_version": parser_version,
        "content_sha256": content_sha,
        "outline": outline_obj,
        "status": "ready",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    code_outlines.append(new_row)
    _save("code_outlines.json", code_outlines)

    _log("ok", repository_id=rid, repo_file_id=rfid, outline_id=new_row["id"], detail="created_ready")
    return {"repository": repo, "repo_file": rf, "outline": new_row}

def whoami(apiKey, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    start = time.time()

    if not isinstance(apiKey, str) or apiKey.strip() == "":
        return _err("UNAUTHORIZED", "missing or invalid apiKey")

    # No credentials schema provided; authenticate by presence of any stored key in conventional files.
    cred = None
    for fname in ("api_keys.json", "credentials.json", "keys.json"):
        p = os.path.join(_DB, fname)
        if not os.path.exists(p):
            continue
        rows = _load(fname)
        if isinstance(rows, list):
            for r in rows:
                if apiKey == r.get("apiKey") or apiKey == r.get("key") or apiKey == r.get("token") or apiKey == r.get("id"):
                    cred = r
                    cred["_file"] = fname
                    break
        if cred:
            break

    if cred is None:
        # If no key store exists at all, accept any non-empty apiKey (offline single-tenant mode).
        any_store_exists = any(os.path.exists(os.path.join(_DB, f)) for f in ("api_keys.json", "credentials.json", "keys.json"))
        if any_store_exists:
            return _err("UNAUTHORIZED", "INVALID_AUTH: apiKey not recognized")
        cred = {"id": apiKey, "apiKey": apiKey, "scopes": ["*"], "status": "active"}

    now = _now()

    # Rate/quota: if request_logs.json exists, report basic consumption. Otherwise zero.
    usage = {"rate_limit": None, "quota": None, "recent_requests_1m": 0}
    logs_path = os.path.join(_DB, "request_logs.json")
    if os.path.exists(logs_path):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            # count last 60 seconds based on ts if parseable
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            c = 0
            for r in logs[-5000:]:
                ts = r.get("ts") or r.get("timestamp")
                if isinstance(ts, str) and ts.endswith("Z"):
                    try:
                        dt = datetime.datetime.fromisoformat(ts[:-1])
                        if dt >= cutoff:
                            c += 1
                    except Exception:
                        pass
            usage["recent_requests_1m"] = c

        logs = logs if isinstance(logs, list) else []
        logs.append({
            "id": _new_id("log"),
            "endpoint": "whoami",
            "credential_id": cred.get("id"),
            "status": "ok",
            "ts": now,
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("request_logs.json", logs)

    return {
        "identity": {
            "credential_id": cred.get("id"),
            "label": cred.get("name") or cred.get("label"),
            "status": cred.get("status", "active"),
        },
        "scopes": cred.get("scopes") if isinstance(cred.get("scopes"), list) else ["*"],
        "usage": usage,
    }

def list_repositories(apiKey, status=None, nameQuery=None, page=None, pageSize=None, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    start = time.time()
    if not isinstance(apiKey, str) or apiKey.strip() == "":
        return _err("UNAUTHORIZED", "missing or invalid apiKey")

    # Authenticate if credential store exists; otherwise accept any key.
    recognized = False
    for fname in ("api_keys.json", "credentials.json", "keys.json"):
        p = os.path.join(_DB, fname)
        if not os.path.exists(p):
            continue
        rows = _load(fname)
        if isinstance(rows, list):
            for r in rows:
                if apiKey == r.get("apiKey") or apiKey == r.get("key") or apiKey == r.get("token") or apiKey == r.get("id"):
                    recognized = True
                    break
        if recognized:
            break
    any_store_exists = any(os.path.exists(os.path.join(_DB, f)) for f in ("api_keys.json", "credentials.json", "keys.json"))
    if any_store_exists and not recognized:
        return _err("UNAUTHORIZED", "INVALID_AUTH: apiKey not recognized")

    # Validate filters/pagination
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "missing"):
            return _err("VALIDATION_ERROR", "invalid status filter")
    if nameQuery is not None and not isinstance(nameQuery, str):
        return _err("VALIDATION_ERROR", "nameQuery must be a string")
    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")

    repos = _load("repositories.json")
    if not isinstance(repos, list):
        repos = []

    nq = nameQuery.lower() if isinstance(nameQuery, str) and nameQuery.strip() != "" else None
    filtered = []
    for r in repos:
        if status is not None and r.get("status") != status:
            continue
        if nq is not None:
            nm = r.get("name") or ""
            if not isinstance(nm, str) or nq not in nm.lower():
                continue
        filtered.append(r)

    filtered.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("id") or ""))

    total = len(filtered)
    start_i = (page - 1) * pageSize
    end_i = start_i + pageSize
    items = filtered[start_i:end_i]
    has_more = end_i < total

    now = _now()
    logs_path = os.path.join(_DB, "request_logs.json")
    if os.path.exists(logs_path):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("log"),
            "endpoint": "list_repositories",
            "status": "ok",
            "ts": now,
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("request_logs.json", logs)

    return {
        "items": items,
        "page": page,
        "pageSize": pageSize,
        "total": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
    }

def create_repository(apiKey, name, repo_root, status=None, active_profile_id=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mk_id(prefix):
        # Use same id style as existing rows (prefix embedded in id content, not as a separator token)
        return prefix + "_" + hashlib.sha256(f"{prefix}|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _mklog_id():
        return "reqlog_" + hashlib.sha256(f"{now}|create_repository|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _log(status_s, repository_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mklog_id(),
                "endpoint": "create_repository",
                "status": status_s,
                "repository_id": repository_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    # apiKey is explicit. In this datastore it's commonly a repository id; accept any non-empty string.
    if not isinstance(apiKey, str) or apiKey.strip() == "":
        _log("error", detail="unauthorized:apiKey_missing")
        return _err("UNAUTHORIZED", "missing or invalid apiKey")

    if not isinstance(name, str) or name.strip() == "":
        _log("error", detail="validation:name")
        return _err("VALIDATION_ERROR", "name is required and must be non-empty", name=name)
    if not isinstance(repo_root, str) or repo_root.strip() == "":
        _log("error", detail="validation:repo_root")
        return _err("VALIDATION_ERROR", "repo_root is required and must be non-empty", repo_root=repo_root)

    nm = name.strip()
    # Normalize root (absolute)
    root_in = repo_root.strip()
    if not os.path.isabs(root_in):
        _log("error", detail="validation:repo_root_abs")
        return _err("VALIDATION_ERROR", "repo_root must be an absolute path", repo_root=repo_root)
    root_norm = os.path.abspath(root_in)

    st = status if status is not None else "active"
    if not isinstance(st, str) or st not in ("active", "disabled", "missing"):
        _log("error", detail="validation:status")
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, missing", status=status)

    repos = _load("repositories.json")
    if not isinstance(repos, list):
        repos = []

    # Unique constraint is unique(repo_root) per schema; DO NOT enforce unique(name)
    for r in repos:
        if not isinstance(r, dict):
            continue
        if isinstance(r.get("repo_root"), str) and os.path.abspath(r["repo_root"]) == root_norm:
            _log("error", repository_id=r.get("id"), detail="conflict:unique(repo_root)")
            return _err("CONFLICT", "Repository with the same repo_root already exists (unique(repo_root))", repo_root=root_norm, existing_id=r.get("id"))

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    apid = active_profile_id
    if apid is not None:
        if not isinstance(apid, str) or apid.strip() == "":
            _log("error", detail="validation:active_profile_id")
            return _err("VALIDATION_ERROR", "active_profile_id must be a non-empty string or null", active_profile_id=active_profile_id)
        apid = apid.strip()
        # Since repo doesn't exist yet, we can only validate that this profile exists and is active;
        # repository ownership can't match yet, so treat as validation error if trying to bind cross-repo.
        p = next((pp for pp in profiles if isinstance(pp, dict) and pp.get("id") == apid), None)
        if not isinstance(p, dict):
            _log("error", detail="not_found:active_profile_id")
            return _err("NOT_FOUND", "active_profile_id does not exist", active_profile_id=apid)
        if p.get("status") != "active":
            _log("error", detail="validation:active_profile_id_inactive")
            return _err("VALIDATION_ERROR", "active_profile_id must refer to an active profile", active_profile_id=apid)

        # Also enforce business rule: "Must belong to same repository" is impossible for a new repo; forbid attaching.
        _log("error", detail="validation:active_profile_id_repo_mismatch")
        return _err("VALIDATION_ERROR", "active_profile_id cannot be set when creating a new repository; set it after creating by using set_profile or updating the repository", active_profile_id=apid)

    new_repo = {
        "id": _mk_id("fcs_repo"),
        "name": nm,
        "repo_root": root_norm,
        "active_profile_id": None,
        "status": st,
        "last_scan_at": None,
        "created_at": now,
        "updated_at": now,
    }
    repos.append(new_repo)
    _save("repositories.json", repos)

    _log("ok", repository_id=new_repo["id"], detail="created")
    return {"repository": new_repo}

def scan_repository(apiKey, repository_id, full=True, force=False, **_extra):
    import json, os, datetime, hashlib, fnmatch, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mklog_id():
        return "reqlog_" + hashlib.sha256(f"{now}|scan_repository|{time.time()}".encode("utf-8")).hexdigest()[:24]

    def _log(status_s, repository_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _mklog_id(),
                "endpoint": "scan_repository",
                "status": status_s,
                "repository_id": repository_id,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    # apiKey is bearer-like; accept any non-empty value (no credential store exists).
    if not isinstance(apiKey, str) or not apiKey.strip():
        _log("error", detail="unauthorized:apiKey_missing")
        return _err("UNAUTHORIZED", "Invalid apiKey.")
    if not isinstance(repository_id, str) or not repository_id.strip():
        _log("error", detail="validation:repository_id")
        return _err("VALIDATION_ERROR", "repository_id must be a non-empty string.")
    if full is None:
        full = True
    if force is None:
        force = False
    if not isinstance(full, bool):
        _log("error", repository_id=repository_id, detail="validation:full")
        return _err("VALIDATION_ERROR", "full must be a boolean.")
    if not isinstance(force, bool):
        _log("error", repository_id=repository_id, detail="validation:force")
        return _err("VALIDATION_ERROR", "force must be a boolean.")

    repos = _load("repositories.json")
    repo_files = _load("repo_files.json")
    if not isinstance(repos, list):
        repos = []
    if not isinstance(repo_files, list):
        repo_files = []

    repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == repository_id), None)
    if not repo:
        _log("error", repository_id=repository_id, detail="not_found:repository")
        return _err("NOT_FOUND", "Repository does not exist", repository_id=repository_id)

    if repo.get("status") == "disabled" and not force:
        _log("error", repository_id=repository_id, detail="invalid_transition:disabled_requires_force")
        return _err("INVALID_TRANSITION", "Repository is disabled; pass force=true to scan", repository_id=repository_id)

    repo_root = repo.get("repo_root")
    if not isinstance(repo_root, str) or not repo_root.strip() or not os.path.isabs(repo_root):
        _log("error", repository_id=repository_id, detail="validation:repo_root")
        return _err("VALIDATION_ERROR", "Repository repo_root is invalid", repository_id=repository_id)

    def _default_ignore_reason(relpath):
        rp = relpath.replace("\\", "/")
        parts = rp.split("/")
        for seg in parts:
            if seg in (".git", "__pycache__", "node_modules", "dist", ".venv", ".idea", ".vscode"):
                if seg in (".idea", ".vscode"):
                    return f"default_ignore:ide_folder:{seg}/"
                return f"default_ignore:{seg}/"
        base = parts[-1] if parts else rp
        if base.endswith(".pyc"):
            return "default_ignore:*.pyc"
        return None

    def _make_file_id():
        return "fcs_fil_" + hashlib.sha256(f"file|{repository_id}|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24]

    # Build index for existing rows by (repository_id, relative_path)
    by_key = {}
    for rf in repo_files:
        if not isinstance(rf, dict):
            continue
        if rf.get("repository_id") == repository_id and isinstance(rf.get("relative_path"), str):
            by_key[(repository_id, rf["relative_path"])] = rf

    seen = set()

    # If repo_root doesn't exist, transition repository to missing (legal from any state)
    if not os.path.exists(repo_root):
        # transition repository status
        if repo.get("status") != "missing":
            repo["status"] = "missing"
            repo["updated_at"] = now
        # mark all repo_files as missing
        changed = False
        for rf in repo_files:
            if isinstance(rf, dict) and rf.get("repository_id") == repository_id and rf.get("status") != "missing":
                rf["status"] = "missing"
                rf["updated_at"] = now
                changed = True
        repo["last_scan_at"] = None
        _save("repositories.json", repos)
        if changed:
            _save("repo_files.json", repo_files)
        _log("ok", repository_id=repository_id, detail="root_missing")
        return {"repository": repo, "scan": {"full": full, "force": force, "status": "missing_root"}}

    # Walk filesystem
    for dirpath, dirnames, filenames in os.walk(repo_root):
        rel_dir = os.path.relpath(dirpath, repo_root).replace("\\", "/")
        if rel_dir == ".":
            rel_dir = ""
        # Prune ignored directories
        pruned = []
        for d in list(dirnames):
            rp = (rel_dir + "/" + d).lstrip("/")
            reason = _default_ignore_reason(rp + "/")
            if reason:
                pruned.append(d)
        for d in pruned:
            if d in dirnames:
                dirnames.remove(d)

        # Record directory entries too
        for d in dirnames:
            rp = (rel_dir + "/" + d).lstrip("/")
            if rp == "":
                continue
            key = (repository_id, rp)
            seen.add(key)
            reason = _default_ignore_reason(rp + "/")
            row = by_key.get(key)
            if row is None:
                row = {
                    "id": _make_file_id(),
                    "repository_id": repository_id,
                    "relative_path": rp,
                    "is_directory": True,
                    "extension": None,
                    "size_bytes": None,
                    "mtime": None,
                    "content_sha256": None,
                    "ignored_reason": reason,
                    "status": "ignored" if reason else "indexed",
                    "created_at": now,
                    "updated_at": now,
                }
                repo_files.append(row)
                by_key[key] = row
            else:
                new_status = "ignored" if reason else "indexed"
                if row.get("status") != new_status or row.get("ignored_reason") != reason or row.get("is_directory") is not True:
                    row["is_directory"] = True
                    row["extension"] = None
                    row["size_bytes"] = None
                    row["ignored_reason"] = reason
                    row["status"] = new_status
                    row["updated_at"] = now

        for fn in filenames:
            rp = (rel_dir + "/" + fn).lstrip("/")
            key = (repository_id, rp)
            seen.add(key)

            reason = _default_ignore_reason(rp)
            abs_p = os.path.join(dirpath, fn)
            try:
                st = os.stat(abs_p)
                size = int(st.st_size)
                mtime = datetime.datetime.utcfromtimestamp(st.st_mtime).replace(microsecond=0).isoformat() + "Z"
            except Exception:
                size = None
                mtime = None

            ext = None
            if "." in fn and not fn.endswith("."):
                ext = fn.rsplit(".", 1)[1].lower()
            # Enforce extension lowercase constraint
            if ext is not None and ext != ext.lower():
                ext = ext.lower()

            row = by_key.get(key)
            new_status = "ignored" if reason else "indexed"
            if row is None:
                row = {
                    "id": _make_file_id(),
                    "repository_id": repository_id,
                    "relative_path": rp,
                    "is_directory": False,
                    "extension": ext,
                    "size_bytes": None if reason else size,
                    "mtime": mtime,
                    "content_sha256": row.get("content_sha256") if isinstance(row, dict) else None,
                    "ignored_reason": reason,
                    "status": new_status,
                    "created_at": now,
                    "updated_at": now,
                }
                # content_sha256 unknown until computed by other workflows; keep null
                row["content_sha256"] = None
                repo_files.append(row)
                by_key[key] = row
            else:
                # Upsert update; keep content_sha256 if present and mtime unchanged, otherwise clear to force recompute
                prev_mtime = row.get("mtime")
                if mtime and prev_mtime and mtime != prev_mtime:
                    row["content_sha256"] = None
                row["is_directory"] = False
                row["extension"] = ext
                row["ignored_reason"] = reason
                row["status"] = new_status
                row["mtime"] = mtime
                # size_bytes constraint: null for directories; >=0 for files. For ignored files, allow null to avoid reading.
                row["size_bytes"] = None if (reason or size is None) else max(0, int(size))
                row["updated_at"] = now

    # Mark removed files as missing (do not delete)
    changed_missing = False
    for rf in repo_files:
        if not isinstance(rf, dict):
            continue
        if rf.get("repository_id") != repository_id:
            continue
        rp = rf.get("relative_path")
        if not isinstance(rp, str) or rp == "":
            continue
        if (repository_id, rp) not in seen:
            if rf.get("status") != "missing":
                rf["status"] = "missing"
                rf["updated_at"] = now
                changed_missing = True

    repo["last_scan_at"] = now
    repo["updated_at"] = now
    # If it was missing, bring back to active unless it was disabled (respect disabled)
    if repo.get("status") == "missing":
        repo["status"] = "active"

    _save("repositories.json", repos)
    _save("repo_files.json", repo_files)

    _log("ok", repository_id=repository_id, detail="scanned")
    return {"repository": repo, "scan": {"full": full, "force": force, "status": "ok", "last_scan_at": now}}

def list_repo_files(apiKey, repository_id, prefix=None, status=None, is_directory=None, extensions=None, page=1, pageSize=100, sort="relative_path", order="asc", **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("UNAUTHORIZED", "Invalid apiKey.")
    if not isinstance(repository_id, str) or not repository_id.strip():
        return _err("VALIDATION_ERROR", "repository_id must be a non-empty string.")

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 100
    if sort is None:
        sort = "relative_path"
    if order is None:
        order = "asc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 500:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 500.")
    if sort not in ("relative_path", "mtime", "size_bytes", "status"):
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.")
    if is_directory is not None and not isinstance(is_directory, bool):
        return _err("VALIDATION_ERROR", "is_directory must be a boolean if provided.")

    allowed_status = {"indexed", "missing", "ignored", "error"}
    if status is not None:
        if not isinstance(status, list) or any((not isinstance(s, str) or s not in allowed_status) for s in status):
            return _err("VALIDATION_ERROR", "status must be an array of valid status strings.")
        status_set = set(status)
    else:
        status_set = None

    def _norm_prefix(p):
        p = p.replace("\\", "/").strip()
        if p == "":
            return None
        p = p.lstrip("/")
        segs = []
        for part in p.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                if not segs:
                    return None
                segs.pop()
            else:
                segs.append(part)
        out = "/".join(segs)
        if out and not out.endswith("/"):
            out += "/"
        return out

    pref = None
    if prefix is not None:
        if not isinstance(prefix, str):
            return _err("VALIDATION_ERROR", "prefix must be a string if provided.")
        pref = _norm_prefix(prefix)
        if pref is None and prefix.strip() != "":
            return _err("VALIDATION_ERROR", "prefix is invalid (path traversal or malformed).")

    ext_set = None
    if extensions is not None:
        if not isinstance(extensions, list) or any(not isinstance(e, str) for e in extensions):
            return _err("VALIDATION_ERROR", "extensions must be an array of strings.")
        norm = []
        for e in extensions:
            ee = e.strip().lower()
            if ee.startswith("."):
                ee = ee[1:]
            if ee == "" or "." in ee:
                return _err("VALIDATION_ERROR", "extensions must be lowercase strings without leading dots.")
            norm.append(ee)
        ext_set = set(norm)

    repos = _load("repositories.json")
    repo = next((r for r in repos if r.get("id") == repository_id), None)
    if not repo:
        return _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)

    # No ACL model present in schema; treat authenticated caller as authorized.
    rows = _load("repo_files.json")
    out = []
    for rf in rows:
        if rf.get("repository_id") != repository_id:
            continue
        relp = rf.get("relative_path")
        if not isinstance(relp, str) or relp == "":
            continue

        if pref:
            # prefix is directory prefix; include exact directory itself if it matches without trailing slash
            if not (relp == pref[:-1] or relp.startswith(pref)):
                continue

        if status_set is not None and rf.get("status") not in status_set:
            continue
        if is_directory is not None and bool(rf.get("is_directory")) != is_directory:
            continue
        if ext_set is not None:
            if rf.get("is_directory"):
                continue
            ext = rf.get("extension")
            if not isinstance(ext, str) or ext.lower() not in ext_set:
                continue

        out.append(rf)

    reverse = (order == "desc")

    def _sort_key(r):
        v = r.get(sort)
        if sort in ("size_bytes",):
            return (-1 if v is None else v)
        if sort in ("mtime",):
            # mtime is ISO string or None
            return "" if v is None else v
        if sort in ("status", "relative_path"):
            return "" if v is None else str(v)
        return "" if v is None else str(v)

    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    start = (page - 1) * pageSize
    end = start + pageSize
    items = out[start:end]
    has_more = end < total

    return {
        "repository_id": repository_id,
        "page": page,
        "pageSize": pageSize,
        "total": total,
        "has_more": has_more,
        "items": items,
    }

def create_profile(apiKey, repository_id, name, description=None, include_globs=None, exclude_globs=None, include_extensions=None, recursive_default=True, max_size_default_bytes=1048576, encoding_default="utf8", status="active", **_extra):
    import json, os, datetime, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0019000" if __import__("os").path.isdir("./environment_mix/0019000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow()
    now = now_dt.replace(microsecond=0).isoformat() + "Z"

    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("UNAUTHORIZED", "Invalid apiKey.")
    if not isinstance(repository_id, str) or not repository_id.strip():
        return _err("VALIDATION_ERROR", "repository_id must be a non-empty string.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string if provided.")

    if include_globs is None:
        include_globs = []
    if exclude_globs is None:
        exclude_globs = []
    if include_extensions is None:
        include_extensions = []

    if not isinstance(include_globs, list) or any(not isinstance(g, str) for g in include_globs):
        return _err("VALIDATION_ERROR", "include_globs must be an array of strings.")
    if not isinstance(exclude_globs, list) or any(not isinstance(g, str) for g in exclude_globs):
        return _err("VALIDATION_ERROR", "exclude_globs must be an array of strings.")
    if not isinstance(include_extensions, list) or any(not isinstance(e, str) for e in include_extensions):
        return _err("VALIDATION_ERROR", "include_extensions must be an array of strings.")
    if not isinstance(recursive_default, bool):
        return _err("VALIDATION_ERROR", "recursive_default must be a boolean.")
    if not isinstance(max_size_default_bytes, int):
        return _err("VALIDATION_ERROR", "max_size_default_bytes must be an integer.")
    if max_size_default_bytes < 1024 or max_size_default_bytes > 104857600:
        return _err("VALIDATION_ERROR", "max_size_default_bytes must be within [1024, 104857600].")
    allowed_enc = {"utf8", "utf-8", "ascii", "latin1", "utf16le", "ucs2"}
    if not isinstance(encoding_default, str) or encoding_default not in allowed_enc:
        return _err("VALIDATION_ERROR", "encoding_default is invalid.")
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "archived"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'archived'.")

    # basic glob sanity: disallow absolute paths and traversal; allow typical glob meta
    def _valid_glob(g):
        gg = g.strip().replace("\\", "/")
        if gg == "":
            return False
        if gg.startswith("/"):
            return False
        # reject segments that are '..' to avoid traversal intent
        if any(seg == ".." for seg in gg.split("/")):
            return False
        return True

    for g in include_globs:
        if not _valid_glob(g):
            return _err("VALIDATION_ERROR", "Invalid include_glob.", glob=g)
    for g in exclude_globs:
        if not _valid_glob(g):
            return _err("VALIDATION_ERROR", "Invalid exclude_glob.", glob=g)

    # normalize extensions
    norm_ext = []
    for e in include_extensions:
        ee = e.strip().lower()
        if ee.startswith("."):
            ee = ee[1:]
        if ee == "" or "." in ee:
            return _err("VALIDATION_ERROR", "include_extensions must be lowercase strings without dots.", extension=e)
        if ee != e.strip().lower().lstrip("."):
            # accept but normalized anyway
            pass
        norm_ext.append(ee)
    include_extensions = norm_ext

    repos = _load("repositories.json")
    repo = next((r for r in repos if r.get("id") == repository_id), None)
    if not repo:
        return _err("NOT_FOUND", "Repository not found.", repository_id=repository_id)

    profiles = _load("profiles.json")

    # uniqueness within repository
    for p in profiles:
        if p.get("repository_id") == repository_id and p.get("name") == name.strip():
            return _err("CONFLICT", "Profile name already exists in repository.", name=name.strip())

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now + '|' + os.urandom(16).hex()).encode('utf-8')).hexdigest()[:24]}"

    row = {
        "id": _new_id("prof"),
        "repository_id": repository_id,
        "name": name.strip(),
        "description": description,
        "include_globs": include_globs,
        "exclude_globs": exclude_globs,
        "include_extensions": include_extensions,
        "recursive_default": bool(recursive_default),
        "max_size_default_bytes": int(max_size_default_bytes),
        "encoding_default": encoding_default,
        "status": status,
        "created_at": now,
        "updated_at": now,
    }

    profiles.append(row)
    _save("profiles.json", profiles)

    return {"profile": row}
